const vars={},space={},components={};
await Promise.all(Object.entries(F.variables).map(async([k,id])=>vars[k]=await figma.variables.getVariableByIdAsync(id)));
const remoteSpace={4:'6991c8db166da9c4d23de28830fc570f19aba2e9',8:'15bb1c0f339146e931cf0dc15f89ed57dcbd907e',16:'16bc6f84b6e7e20e4234ef79030ee580ec0f4505',24:'be3115966ea99eef888c9f25751b54695c7e88d2',32:'9acadea8b7c7c9884455b896e21c88b8bc62d6da'};await Promise.all(Object.entries(F.spacing).map(async([k,id])=>{space[k]=await figma.variables.getVariableByIdAsync(id);if(!space[k]&&remoteSpace[k])space[k]=await figma.variables.importVariableByKeyAsync(remoteSpace[k]);if(!space[k])throw new Error('Missing spacing '+k);}));
await Promise.all(Object.entries(F.components).map(async([k,id])=>components[k]=await figma.getNodeByIdAsync(id)));
const radius=await figma.variables.getVariableByIdAsync(F.radius);
const created=[],mutated=[],links=[],evidence=[];
function keep(n){created.push(n.id);if('findAll' in n)created.push(...n.findAll(()=>true).map(c=>c.id));return n;}
function paint(k){return figma.variables.setBoundVariableForPaint({type:'SOLID',color:{r:0,g:0,b:0}},'color',vars[k]);}
function fill(n,k){n.fills=[paint(k)];}
function pad(n,v){for(const k of ['paddingLeft','paddingRight','paddingTop','paddingBottom'])n.setBoundVariable(k,space[v]);}
function round(n){for(const k of ['topLeftRadius','topRightRadius','bottomLeftRadius','bottomRightRadius'])n.setBoundVariable(k,radius);}
function box(parent,name,width,dir='VERTICAL',gap=16,padding=0,color=null){const n=figma.createAutoLayout(dir);n.name=name;n.clipsContent=false;parent.appendChild(n);n.resize(width,100);n.layoutSizingHorizontal='FIXED';n.layoutSizingVertical='HUG';n.primaryAxisAlignItems='MIN';n.counterAxisAlignItems=dir==='HORIZONTAL'?'CENTER':'MIN';n.setBoundVariable('itemSpacing',space[gap]);pad(n,padding);n.fills=color?[paint(color)]:[];created.push(n.id);return n;}
function text(parent,value,width,kind='Body',color='navy'){const n=figma.createText();n.name=value.split('\n')[0].slice(0,60);n.fontName={family:'IBM Plex Sans',style:'Regular'};n.textStyleId=F.styles[kind];n.textAutoResize='HEIGHT';n.resize(width,24);n.characters=value;n.fills=[paint(color)];parent.appendChild(n);n.textAutoResize='HEIGHT';n.layoutSizingHorizontal='FIXED';n.layoutSizingVertical='HUG';created.push(n.id);return n;}
function instance(parent,key,props={},width=null){const n=components[key].createInstance();parent.appendChild(n);const p={};for(const [name,value] of Object.entries(props))for(const key of Object.keys(n.componentProperties))if(key===name||key.startsWith(name+'#'))p[key]=value;n.setProperties(p);if(width){n.resize(width,n.height);if(key==='field'){n.primaryAxisSizingMode='AUTO';for(const c of n.children)if(c.type==='FRAME'){c.resize(width,c.height);c.layoutSizingHorizontal='FILL';}}}keep(n);return n;}
function action(parent,label,target,style='Primary'){const n=instance(parent,'button'+style,{Label:label},Math.max(132,Math.min(280,label.length*7.5+36)));if(target&&style!=='Disabled')links.push({id:n.id,target});return n;}
function badge(parent,label,tone='Neutral'){return instance(parent,'tag'+tone,{Label:label});}
function card(parent,title,width,sub=null){const n=box(parent,title,width,'VERTICAL',16,24,'white');round(n);n.strokes=[paint('line')];n.strokeWeight=1;text(n,title,width-48,'Section');if(sub)text(n,sub,width-48,'Caption','muted');return n;}
function note(parent,title,detail,width,tone='Information'){const colors={Information:['blueTint','blue'],Success:['greenTint','green'],Pending:['amberTint','amber'],Attention:['redTint','red']};const [bg,fg]=colors[tone];const n=box(parent,title,width,'VERTICAL',6,16,bg);round(n);text(n,title,width-32,'Label',fg);if(detail)text(n,detail,width-32,'Caption',fg);return n;}
function pair(parent,label,value,width=320){const n=box(parent,label,width,'VERTICAL',4);text(n,label,width,'Caption','muted');text(n,value,width,'Label');return n;}
function field(parent,label,value,width=330){return instance(parent,'field',{Label:label,Value:value},width);}
function metrics(parent,list){const row=box(parent,'Metrics',1156,'HORIZONTAL',16);for(const [label,value,detail]of list)instance(row,'metric',{Label:label,Value:value,Detail:detail},277);return row;}
function table(parent,headers,rows,widths){const width=widths.reduce((a,b)=>a+b,0);const outer=box(parent,'Table',width,'VERTICAL',0,0,'white');round(outer);outer.strokes=[paint('line')];outer.strokeWeight=1;
function tr(values,head=false,index=0){const r=box(outer,head?'Table header':'Row '+(index+1),width,'HORIZONTAL',0,0,head?'canvas':(index%2?'canvas':'white'));r.resize(width,head?42:68);r.layoutSizingVertical='FIXED';r.counterAxisAlignItems='CENTER';for(let i=0;i<values.length;i++){const cell=box(r,'Cell '+headers[i],widths[i],'HORIZONTAL',0,12);cell.resize(widths[i],head?42:68);cell.layoutSizingVertical='FIXED';if(typeof values[i]==='object'&&values[i].badge){badge(cell,values[i].badge,values[i].tone);}else text(cell,String(values[i]),widths[i]-24,head?'Caption':'Label',head?'muted':'navy');}return r;}tr(headers,true);rows.forEach((v,i)=>tr(v,false,i));return outer;}
function lineItems(parent,items,width){for(const [label,value]of items){const r=box(parent,label,width,'HORIZONTAL',16);text(r,label,width-156,'Body','muted');text(r,value,140,'Label');}}
function patient(parent,state='In care'){const n=box(parent,'Patient identity / admission context',1156,'HORIZONTAL',24,20,'white');round(n);n.strokes=[paint('line')];n.strokeWeight=1;const a=box(n,'Patient',220,'VERTICAL',4);text(a,'Anita Rao',220,'Title');text(a,'54 years · Female · UHID-004829',220,'Caption','muted');const b=box(n,'Admission',420,'VERTICAL',4);text(b,'IP-2026-01301  ·  Ward B / Bed 203',420,'Label');text(b,'Admitted 06 Oct, 09:00  ·  Dr Meera Shah',420,'Caption','muted');const c=box(n,'Status',340,'HORIZONTAL',8);badge(c,state,state==='Discharged'?'Success':state==='Discharge in progress'?'Pending':'Information');badge(c,'Insurance recorded','Neutral');return n;}
const roleNav={admin:['overview','admission','doctor','nurse','pharmacy','lab','billing','insurance','discharge','documents','exceptions'],admission:['overview','admission','insurance'],doctor:['overview','doctor','discharge'],nurse:['overview','nurse','discharge'],pharmacy:['overview','pharmacy','discharge'],lab:['overview','lab'],billing:['overview','billing','insurance','discharge','documents'],insurance:['overview','insurance','discharge']};
const navNames={overview:'Hospital overview',admission:'Admissions & beds',doctor:'Doctor workspace',nurse:'Nursing workspace',pharmacy:'Pharmacy',lab:'Lab worklist',billing:'Charges & payments',insurance:'Insurance paperwork',discharge:'Discharge clearance',documents:'Final documents',exceptions:'Admin exceptions'};
async function shell(key,title,section,role,desc,hasPatient=false){const root=await figma.getNodeByIdAsync(ROOTS[key]);if(root.children.length)throw new Error('Screen already populated: '+key);root.fills=[paint('canvas')];const side=box(root,'Role navigation',216,'VERTICAL',8,16,'white');side.resize(216,1100);side.layoutSizingVertical='FIXED';side.strokes=[paint('line')];side.strokeWeight=1;const brand=box(side,'Hospital identity',184,'HORIZONTAL',12);const mon=box(brand,'Brand monogram',40,'VERTICAL',0,8,'teal');round(mon);text(mon,'H',24,'Title','white');text(brand,'HIMS\nCitycare Hospital',126,'Label');text(side,'INPATIENT WORKSPACE',184,'Caption','subtle');for(const dest of roleNav[role]){const current=dest===key||(dest==='discharge'&&key==='ready');const n=instance(side,current?'navActive':'navDefault',{Label:navNames[dest]},184);links.push({id:n.id,target:dest});}const spare=box(side,'Flexible space',184);spare.layoutSizingVertical='FILL';text(side,'Need help?\nContact your hospital admin',184,'Caption','muted');action(side,'Review all roles','guide','Secondary');
const app=box(root,'Application',1224,'VERTICAL',0);app.resize(1224,1100);app.layoutSizingVertical='FIXED';const bar=box(app,'Top bar',1224,'HORIZONTAL',24,16,'white');bar.resize(1224,72);bar.layoutSizingVertical='FIXED';bar.setBoundVariable('paddingLeft',space[32]);bar.setBoundVariable('paddingRight',space[32]);text(bar,'Search patient name, admission code or bed',650,'Body','subtle');text(bar,'10 Oct 2026 · 09:00 IST',246,'Caption','muted');badge(bar,role==='admin'?'Hospital admin':role.charAt(0).toUpperCase()+role.slice(1)+' staff','Information');
const body=box(app,'Main workspace',1224,'VERTICAL',20,32);text(body,section.toUpperCase()+'  /  USED BY '+role.toUpperCase(),1156,'Caption','teal');const head=box(body,'Page heading',1156,'HORIZONTAL',24);const titlecol=box(head,'Title and purpose',820,'VERTICAL',6);text(titlecol,title,820,'Heading');text(titlecol,desc,820,'Body','muted');if(hasPatient)patient(body,key==='documents'?'Discharged':['discharge','ready'].includes(key)?'Discharge in progress':'In care');return {root,body};}
function finish(key,root){root.placeholder=false;mutated.push(root.id);evidence.push({key,id:root.id,name:root.name,width:root.width,height:root.height,descendants:root.findAll(()=>true).length,fonts:[...new Set(root.findAllWithCriteria({types:['TEXT']}).map(t=>t.fontName.family))]});}
